  def support_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var support_assessment: Ore_Hold_Mining_Guard_Supervisor.SupportAssessment.Type = $

  def put_support_assessment(value : Ore_Hold_Mining_Guard_Supervisor.SupportAssessment.Type) : Unit = {
    Contract(
      Modifies(support_assessment),
      Ensures(
        support_assessment == value
      )
    )
    Spec {
      support_assessment = value
    }

    Art.putValue(support_assessment_Id, Ore_Hold_Mining_Guard_Supervisor.SupportAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class MiningSupportQualificationOwner_Initialization_Api (
  val id: Art.BridgeId,
  val mining_support_Id : Art.PortId,
  val support_assessment_Id : Art.PortId) extends MiningSupportQualificationOwner_Api

@datatype class MiningSupportQualificationOwner_Operational_Api (
