  @spec var mining_support: Ore_Hold_Mining_Guard_Supervisor.MiningSupportSample = $

  def get_mining_support() : Option[Ore_Hold_Mining_Guard_Supervisor.MiningSupportSample] = {
    Contract(
      Ensures(
